async function post_rect(rect) {
	try {
		const url = new URL("select", location.href);
		url.searchParams.set("pos", rect.dataset.pos);
		const response = await fetch(url, { method: "POST" });
		if (!response.ok) {
			console.error("Selection failed:", response.status);
		}
	} catch (error) {
		console.error("Selection failed:", error);
	}
}
for(const rect of document.getElementsByTagName("rect")) {
	rect.addEventListener("click", async () => { await post_rect (rect) });
}

setInterval(() => {
	location.reload();
	}, 2500);
